using Microsoft.Extensions.AI.Evaluation;
using MyApp.Evaluation.Infrastructure;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation scenarios for the chat agent. Each test method represents a
/// distinct evaluation scenario that measures response quality.
/// </summary>
[TestClass]
public class ChatEvaluationTests : EvaluationTestBase
{
    [TestMethod]
    public async Task Chat_AnswersGreeting_IsCoherentAndFluent()
    {
        var (response, result) = await EvaluateAsync(
            scenarioName: "greeting",
            userMessage: "Hello! Can you introduce yourself?");

        Assert.IsFalse(string.IsNullOrWhiteSpace(response), "Response should not be empty.");
        AssertPassingScores(result, minScore: 3);
    }

    [TestMethod]
    public async Task Chat_AnswersFactualQuestion_IsRelevantAndGrounded()
    {
        var (response, result) = await EvaluateAsync(
            scenarioName: "factual_question",
            userMessage: "What is the capital of France?",
            context: "The capital of France is Paris.");

        Assert.IsFalse(string.IsNullOrWhiteSpace(response), "Response should not be empty.");
        AssertPassingScores(result, minScore: 3);
    }

    [TestMethod]
    public async Task Chat_HandlesAmbiguousQuery_RespondsCoherently()
    {
        var (response, result) = await EvaluateAsync(
            scenarioName: "ambiguous_query",
            userMessage: "Tell me about Mercury.");

        Assert.IsFalse(string.IsNullOrWhiteSpace(response), "Response should not be empty.");

        var coherence = result.Metrics.FirstOrDefault(m =>
            m.Key.Equals("Coherence", StringComparison.OrdinalIgnoreCase));
        Assert.IsTrue(
            coherence.Value?.NumericValue >= 3,
            $"Coherence score {coherence.Value?.NumericValue} is below threshold of 3.");
    }

    private static void AssertPassingScores(EvaluationResult result, int minScore)
    {
        foreach (var metric in result.Metrics)
        {
            if (metric.Value?.NumericValue is not null)
            {
                Assert.IsTrue(
                    metric.Value.NumericValue >= minScore,
                    $"Metric '{metric.Key}' scored {metric.Value.NumericValue}, below threshold {minScore}.");
            }
        }
    }
}

