using Aspire.Hosting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Shared fixture that manages the Aspire app host lifetime and provides
/// configured evaluation reporting for all test classes.
/// </summary>
public sealed class EvaluationFixture : IAsyncDisposable
{
    private DistributedApplication? _app;
    private IChatClient? _chatClient;

    public IChatClient ChatClient => _chatClient
        ?? throw new InvalidOperationException("Call InitializeAsync before accessing ChatClient.");

    public async Task InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    /// <summary>
    /// Creates a <see cref="ReportingConfiguration"/> that writes results to disk
    /// and evaluates response quality using the chat model itself as the evaluator.
    /// </summary>
    public ReportingConfiguration CreateReportingConfiguration()
    {
        var storageDir = Environment.GetEnvironmentVariable("EVALUATION_RESULTS_DIR")
            ?? Path.Combine(AppContext.BaseDirectory, "eval-results");

        var chatConfig = new ChatConfiguration(ChatClient);

        return DiskBasedReportingConfiguration.Create(
            storageDir,
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfig);
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

