using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Base class for evaluation tests. Provides shared fixture access and
/// helper methods for running evaluations.
/// </summary>
[TestClass]
public abstract class EvaluationTestBase
{
    private static readonly EvaluationFixture s_fixture = new();

    protected static IChatClient ChatClient => s_fixture.ChatClient;

    [AssemblyInitialize]
    public static async Task AssemblyInit(TestContext _)
    {
        await s_fixture.InitializeAsync();
    }

    [AssemblyCleanup]
    public static async Task AssemblyCleanup()
    {
        await s_fixture.DisposeAsync();
    }

    /// <summary>
    /// Sends a user message, collects the response, and runs quality evaluators.
    /// Returns the evaluation result for assertion.
    /// </summary>
    protected async Task<(string Response, EvaluationResult Result)> EvaluateAsync(
        string scenarioName,
        string userMessage,
        string? groundTruth = null)
    {
        var config = s_fixture.CreateReportingConfiguration();

        await using var scenarioRun = await config.CreateScenarioRunAsync(scenarioName);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, userMessage)
        };

        var response = await ChatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        var additionalContext = groundTruth is not null
            ? [new EvaluationContext("ground_truth", groundTruth)]
            : Array.Empty<EvaluationContext>();

        var result = await scenarioRun.EvaluateAsync(
            messages,
            response,
            additionalContext);

        return (responseText, result);
    }
}

